(window.LART=window.LART||{})["杂项/标准库/STL容器/set"]="<p><code>STL</code> 容器，集合。<br />\n每个元素在<code>set</code>里面<strong>只会出现一次</strong>。和数学上的集合一样，具有唯一性。<br />\n<strong>默认升序</strong>。<br />\n底层实现是红黑树，特殊的二叉排序树。 </p>\n\n<p>可以简单的把<code>set</code>理解为会自动排序的数组，且会去重。</p>\n\n<h1>常用函数</h1>\n<table>\n<thead>\n<tr>\n<th>函数</th>\n<th>时间复杂度</th>\n<th>备注</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>insert</code></td>\n<td>$O(\\log n)$</td>\n<td>插入</td>\n</tr>\n<tr>\n<td><code>erase</code></td>\n<td>$O(\\log n)$</td>\n<td>删除，元素或迭代器</td>\n</tr>\n<tr>\n<td><code>size</code></td>\n<td>$O(1)$</td>\n<td>大小</td>\n</tr>\n<tr>\n<td><code>empty</code></td>\n<td>$O(1)$</td>\n<td>是否为空</td>\n</tr>\n<tr>\n<td><code>count</code></td>\n<td>$O(\\log n)$</td>\n<td>是否存在</td>\n</tr>\n<tr>\n<td><code>for auto</code></td>\n<td>$O(n)$</td>\n<td>遍历所有元素</td>\n</tr>\n<tr>\n<td><code>begin</code></td>\n<td>$O(1)$</td>\n<td>第一个元素的迭代器</td>\n</tr>\n<tr>\n<td><code>end</code></td>\n<td>$O(1)$</td>\n<td>最后一个元素的<strong>下一个位置</strong>的迭代器</td>\n</tr>\n<tr>\n<td><code>lower_bound</code></td>\n<td>$O(\\log n)$</td>\n<td>大于等于，得到迭代器</td>\n</tr>\n<tr>\n<td><code>upper_bound</code></td>\n<td>$O(\\log n)$</td>\n<td>大于，得到迭代器</td>\n</tr>\n<tr>\n<td><code>++</code></td>\n<td>$O(\\log n)$</td>\n<td>移动迭代器</td>\n</tr>\n<tr>\n<td><code>--</code></td>\n<td>$O(\\log n)$</td>\n<td>移动迭代器</td>\n</tr>\n<tr>\n<td><code>clear</code></td>\n<td>$O(n)$</td>\n<td>清除全部</td>\n</tr>\n<tr>\n<td><code>find</code></td>\n<td>$O(\\log n)$</td>\n<td>找到某个值的迭代器</td>\n</tr>\n</tbody>\n</table>\n<h1>使用</h1>\n\n\n<pre><code class=\"language-cpp\">set&lt;int&gt; st;\nst.insert(3);                 // [3] 插入一个元素\nst.insert(5);                 // [3,5]\nst.insert(1);                 // [1,3,5] 默认升序\nst.insert(5);                 // [1,3,5] 已经有一样的，就不会插入。不重复。\n\ncout &lt;&lt; st.size() &lt;&lt; endl;    // 3 元素个数\n\nst.erase(5);                  // [1,3] 删除指定元素\n\nst.clear();                   // 全部清除\ncout &lt;&lt; st.size() &lt;&lt; endl;    // 0\ncout &lt;&lt; st.emtpy() &lt;&lt; endl;   // true\n\ncout &lt;&lt; st.count(5) &lt;&lt; endl;  // 0 判断5是否在st里面\nst.insert(5);\ncout &lt;&lt; st.count(5) &lt;&lt; endl;  // 1\n\nst.insert(5);\nst.insert(4);\nst.insert(3);\nst.insert(2);\nst.insert(1);\n// 1 2 3 4 5\n// 升序\nfor (auto i : st) {\n    cout &lt;&lt; i &lt;&lt; &quot; &quot;;\n}\ncout &lt;&lt; endl;\n\n// 迭代器，可以认为是指针\n// 使用迭代器的值，加上 星号*\n// st.begin() 指向第一个元素的迭代器\n// st.end() 指向最后一个元素的下一个位置的迭代器\n// 迭代器写法比较复杂，set&lt;int&gt;::iterator it = st.begin();\n// c++11及以上，用auto代替\n\ncout &lt;&lt; *st.begin() &lt;&lt; endl;  // 1 也是最小值\n// cout &lt;&lt; *st.end() &lt;&lt; endl; // 不能这么用\n\n// ++ -- 移动迭代器\ncout &lt;&lt; *(--st.end()) &lt;&lt; endl;  // 5 得到最大值\n\nauto p = st.lower_bound(3);     // 得到大于等于元素的迭代器\nif (p != st.end()) {            // 如果没有，p就是st.end()\n    cout &lt;&lt; *p &lt;&lt; endl;         // 3\n}\n\nauto p2 = st.upper_bound(3);  // 得到大于元素的迭代器\nif (p2 != st.end()) {         // 如果没有，p就是st.end()\n    cout &lt;&lt; *p &lt;&lt; endl;       // 4\n}\n\n// erase也可以删除迭代器代表的那个元素\nst.erase(st.begin());  // 用迭代器删除最小的\nst.erase(--st.end());  // 用迭代器删除最大的\n</code></pre>\n<div class=\"blanks\" style=\"height:2em\"></div>\n<h1>自定义结构体</h1>\n\n<p>结构体需要满足以下条件之一：<br />\n①重载小于号 <br />\n②类的仿函数</p>\n\n<h2>重载小于号</h2>\n<pre><code class=\"language-cpp\">struct Node {\n    int x, y;\n    bool operator&lt;(const Node&amp; other) const {\n        if (x != other.x) {\n            return x &lt; other.x;\n        }\n        return y &lt; other.y;\n    }\n};\n\nint main() {\n    set&lt;Node&gt; st;\n    st.insert({1, 2});\n    return 0;\n}\n</code></pre>\n\n<h2>注意</h2>\n<p>定义多个变量的结构体，<strong>一定要每个变量都进行比较</strong>。<br />\n下面错误示例，只比较了$x$。<br />\n后果：如果$x$相同，$y$不相同，会被当作同一个东西。</p>\n\n\n<pre><code class=\"language-cpp\">struct Node {\n    int x, y;\n    bool operator&lt;(const Node&amp; other) const {\n        return x &lt; other.x;\n    }\n};\nint main() {\n    set&lt;Node&gt; st;\n    st.insert({1, 2});\n    st.insert({1, 3});\n    // {1,2}和{1,3}被当作同一个东西，{1, 3}不插入\n    cout &lt;&lt; st.size() &lt;&lt; endl;\n    // 输出 1\n    cout &lt;&lt; st.begin()-&gt;x &lt;&lt; &quot; &quot; &lt;&lt; st.begin()-&gt;y &lt;&lt; endl;\n    // 输出 1 2\n    return 0;\n}\n\n</code></pre>\n\n<h1>最接近的数字</h1>\n\n\n<pre><code class=\"language-cpp\">set&lt;int&gt; st;\n\nst.insert(2);\nst.insert(3);\nst.insert(6);\nst.insert(7);\n// [2, 3, 6, 7]\n\n// difference\nint ans = 0, dif = 1e9;\nauto p = st.lower_bound(4);\n\n// 找一个&gt;=的，找一个&lt;的，比较一下差值。\nif (p != st.end()) {\n    // st里面有&gt;=4的数字\n    dif = abs(*p - 4);\n    ans = *p;\n}\nif (p != st.begin()) {\n    // st里面有&lt;4的数字\n\n    --p;  // 有才能往前移动\n    if (dif &lt; abs(*p - 4)) {\n        dif = abs(*p - 4);\n        ans = *p;\n    }\n}\n\n</code></pre>\n\n<h1>习题</h1>\n<div class=\"blanks\" style=\"height:1em\"></div>\n<table>\n<thead>\n<tr>\n<th>题号</th>\n<th>链接</th>\n<th>备注</th>\n<th>难度</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>P1059</td>\n<td><a href=\"https://www.luogu.com.cn/problem/P1059\">[NOIP 2006 普及组] 明明的随机数</a></td>\n<td>去重+排序</td>\n<td>橙题</td>\n</tr>\n<tr>\n<td>P4305</td>\n<td></td>\n<td>输出第一次出现的数字</td>\n<td>橙题</td>\n</tr>\n<tr>\n<td>abc347_b</td>\n<td>Substring</td>\n<td>本质不同子串，set去重</td>\n<td>81/橙题</td>\n</tr>\n<tr>\n<td>abc346_c</td>\n<td>Σ</td>\n<td>去重+等差数列</td>\n<td>179/橙题</td>\n</tr>\n<tr>\n<td>P1571</td>\n<td>眼红的Medusa</td>\n<td>某个数是否存在</td>\n<td>橙题</td>\n</tr>\n<tr>\n<td>CF44A</td>\n<td>Indian Summer</td>\n<td>双关键字去重</td>\n<td>红题</td>\n</tr>\n<tr>\n<td>P1678</td>\n<td>烦恼的高考志愿</td>\n<td>最接近的数</td>\n<td>橙题</td>\n</tr>\n<tr>\n<td>P5250</td>\n<td>【深基17.例5】木材仓库</td>\n<td>最接近的数+删除</td>\n<td>橙题</td>\n</tr>\n<tr>\n<td>P2234</td>\n<td>[HNOI2002] 营业额统计</td>\n<td>每个数前面最接近的值</td>\n<td>黄题</td>\n</tr>\n<tr>\n<td>P1878</td>\n<td><a href=\"https://www.luogu.com.cn/problem/P1878\">舞蹈课</a></td>\n<td></td>\n<td>黄题</td>\n</tr>\n<tr>\n<td>CF45C</td>\n<td><a href=\"https://codeforces.com/contest/45/problem/C\">Dancing Lessons</a></td>\n<td></td>\n<td>1900/黄题</td>\n</tr>\n<tr>\n<td>P2161</td>\n<td><a href=\"https://www.luogu.com.cn/problem/P2161\">[SHOI2009] 会场预约</a></td>\n<td>set维护区间。插入，相交的删除；查询区间数量</td>\n<td>蓝题</td>\n</tr>\n<tr>\n<td>abc330_e</td>\n<td><a href=\"https://atcoder.jp/contests/abc330/tasks/abc330_e\">Mex and Update</a></td>\n<td>单点修改，求整个数组的mex</td>\n<td>黄题</td>\n</tr>\n<tr>\n<td>CF1922D</td>\n<td><a href=\"https://codeforces.com/contest/1922/problem/D\">Berserk Monsters</a></td>\n<td></td>\n<td>1900/绿题</td>\n</tr>\n<tr>\n<td>yosupo</td>\n<td><a href=\"https://judge.yosupo.jp/problem/predecessor_problem\">Predecessor Problem</a></td>\n<td>集合插入删除查询，≥，≤</td>\n<td></td>\n</tr>\n</tbody>\n</table>\n";
